  "accLoadError": "Հաշիվները չհաջողվեց բեռնել։ Ստուգեք կապը, թույլատրեք ներդիրի պահոցը և վերաբեռնեք էջը։",
  "accLinkFailedTitle": "Հղումը չհաջողվեց հաստատել",
  "accLinkFailed": "Այս հղումը կարող է ժամկետանց լինել կամ արդեն օգտագործված։ Բացեք Հաշիվը՝ մուտք գործելու կամ նոր նամակ պահանջելու համար։",
