  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "Կաթսան դրեք ամենամեծ այրիչին, միացրեք ՈՒԺԵՂ կրակ և ծածկեք կափարիչով (այդպես ավելի արագ է եռում)։",
