  "Let the water come to a full rolling boil. Meanwhile, start the prep.": "Թողեք, որ ջուրը լավ եռա։ Մինչ այդ սկսեք նախապատրաստումը։",
  "Big bubbles break the surface all the time": "Մեծ պղպջակներն անընդհատ բարձրանում են",
